output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper is obliged to take the available entrance cart before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_station": "at(1,5)",
        "entrance_cart_available": {
          "and": [
            "at_cart_station",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Items may only be picked up while the shopper is pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "has_cart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "item_pickup_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_cart"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying loose goods by hand rather than transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "loose_goods_in_hand": "handFull",
        "cartless_with_hand_item": {
          "and": [
            {
              "not": "has_cart"
            },
            "loose_goods_in_hand"
          ]
        }
      },
      "events": {
        "hand_load_item": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": "loose_goods_in_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "loose_goods_in_hand",
          "hand_load_item"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Before leaving the store, the shopper is obliged to park the cart in the return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "returned_cart": {
          "and": [
            "cart_return_bay",
            "cart_parked_in_return_bay"
          ]
        }
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart"
    }
  },
  {
    "id": "drop_cart_at_return_bay",
    "text": "Whenever the shopper reaches the return bay while still pushing the cart, they are obliged to put the cart down there.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cart_return_bay": "at(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "cart_return_bay",
            "has_cart"
          ]
        },
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_return_bay_with_cart",
      "discharge": "return_cart"
    }
  },
  {
    "id": "reclaim_temporarily_dropped_cart",
    "text": "If a cart is put down anywhere other than the return bay, the shopper is obliged to pick it back up before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "not_return_bay": {
          "not": "cart_return_bay"
        },
        "has_cart": "hasCart"
      },
      "events": {
        "temporary_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_return_bay"
            ]
          },
          "post": {
            "not": "has_cart"
          }
        },
        "recover_cart": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper is prohibited from exiting the supermarket while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "has_cart"
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "has_cart"
            ]
          },
          "post": null
        },
        "exit_without_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "carts_forbidden_in_checkout_side",
    "text": "Carts are prohibited in the eastern checkout and exit side of the store, so the shopper must leave the cart before entering that region.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "checkout_side": {
          "or": [
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_side": {
          "and": [
            "has_cart",
            "checkout_side"
          ]
        }
      },
      "events": {
        "move_cart_into_checkout_side": {
          "pre": {
            "and": [
              "MOVE",
              "has_cart"
            ]
          },
          "post": "cart_in_checkout_side"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_side",
          "move_cart_into_checkout_side"
        ]
      }
    }
  }
]
